failure.message:
AssertionError: Failed to create rider: {"detail":"Riders must provide National Identification Number"}
assert 400 == 200
 +  where 400 = <Response [400]>.status_code

AssertionError: Failed to complete trip: {"detail":"Cannot complete trip"}
assert 400 in [200, 201]
 +  where 400 = <Response [400]>.status_code

AssertionError: Expected 429 for 6th call, got 404: {"detail":"Trip not found"}
assert 404 == 429
 +  where 404 = <Response [404]>.status_code

AssertionError: Failed to accept trip: {"detail":"Trip not found"}
assert 404 == 200
 +  where 404 = <Response [404]>.status_code
